using System.Text.Json.Nodes;
using PowerShapeMcp;
internal static class CurveRotationCheck {
 internal static int Run(string input,string output){var c=JsonNode.Parse(File.ReadAllText(input))!["rows"]!.AsArray().Single(r=>r!["fault"]!.GetValue<string>()=="control")!.AsObject();string root=c["root"]!.GetValue<string>(),id=c["executionId"]!.GetValue<string>(),sha=c["executionSha256"]!.GetValue<string>();var args=c["verificationArguments"]!.AsObject();var reply=c["verificationResult"]!.AsObject();var p=CurveTranslationProof.Execution(root,id,sha,true,true);CurveTranslationProof.Verified(root,reply,args,true);int count=2;var before=ArtifactProof.Verified(root,"responses",p["inspectionRequestId"]!.GetValue<string>(),p["inspectionSha256"]!.GetValue<string>(),16000000);var after=ArtifactProof.Verified(root,"responses",args["inspectionRequestId"]!.GetValue<string>(),args["inspectionSha256"]!.GetValue<string>(),16000000);
 foreach(string fault in new[]{"position","tangent_before","tangent_after","magnitude","flag","solid","native_range","raw_reply","sha"}){bool denied=false;try{var capture=reply["curveCaptureAfter"]!.DeepClone().AsObject();var observed=after.DeepClone().AsObject();switch(fault){case "position":capture["layout"]!["fields"]![0]!["values"]![0]=999;break;case "tangent_before":capture["layout"]!["fields"]![1]!["values"]![0]=999;break;case "tangent_after":capture["layout"]!["fields"]![5]!["values"]![0]=999;break;case "magnitude":capture["layout"]!["fields"]![2]!["values"]![0]=21;break;case "flag":capture["layout"]!["fields"]![3]!["values"]![0]=true;break;case "solid":capture["solidSamples"]!["positions"]![0]!["value"]![0]=0.001;break;case "native_range":observed["entities"]!.AsArray().Single(e=>e!["nativeTypeCode"]!.GetValue<int>()==59)!["geometry"]!["min_rangeRaw"]![0]=999;break;case "raw_reply":var bad=reply.DeepClone().AsObject();bad["copyFenceReleased"]=false;CurveTranslationProof.Verified(root,bad,args,true);break;case "sha":CurveTranslationProof.Execution(root,id,new string('f',64),true,true);break;}if(fault is not("raw_reply"or"sha"))CurveTranslationProof.Post(before,observed,p["captureBefore"]!.AsObject(),capture,new(),10,true);}catch(ReferenceRejected){denied=true;}if(!denied)throw new InvalidDataException("Forged curve rotation proof accepted: "+fault);count++;}
 foreach(string fault in new[]{"angle","axis","profile"}){string mirror=Path.Combine(root,"rotation-proof-forgery-"+Guid.NewGuid().ToString("N"));foreach(string folder in new[]{"responses","ownedexecutions","ownedrotations","rotationplans"}){Directory.CreateDirectory(Path.Combine(mirror,folder));foreach(var f in Directory.GetFiles(Path.Combine(root,folder),"*.json"))File.Copy(f,Path.Combine(mirror,folder,Path.GetFileName(f)));}var plan=p.DeepClone().AsObject();if(fault=="angle")plan["angleDegrees"]=89;else if(fault=="axis")plan["nativeAxis"]![3]=1e-8;else plan["measurementProfile"]=CurveTranslationProof.Profile;string planPath=Path.Combine(mirror,"ownedexecutions",id+".json"),rawPath=Path.Combine(mirror,"responses",id+".json");File.WriteAllText(planPath,plan.ToJsonString());var raw=JsonNode.Parse(File.ReadAllText(rawPath))!.AsObject();raw["plan"]=plan;raw["planSha256"]=FileArtifacts.Sha256(File.ReadAllBytes(planPath));File.WriteAllText(rawPath,raw.ToJsonString());bool denied=false;try{CurveTranslationProof.Execution(mirror,id,FileArtifacts.Sha256(File.ReadAllBytes(rawPath)),true,true);}catch(ReferenceRejected){denied=true;}if(!denied)throw new InvalidDataException("Forged rotation source accepted "+fault);count++;}
 Directory.CreateDirectory(Path.GetDirectoryName(Path.GetFullPath(output))!);File.WriteAllText(output,new JsonObject{["state"]="passed",["cases"]=count,["cadConnectionAttempted"]=false}.ToJsonString());Console.WriteLine($"PASS: {count} actual Framework curve rotation / SDK source and geometry proofs; no CAD.");return 0;}
}
